builder.Services.AddOpenTelemetry()
    .WithMetrics(m => m
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddRuntimeInstrumentation()
        .AddMeter("OrdersApi")
        .AddPrometheusExporter());

// Custom: track cache hit ratio
public sealed class CacheMetrics
{
    private static readonly Counter<long> Hits =
        MeterFactory.Create("OrdersApi").CreateCounter<long>("cache.hits");
    public void Hit() => Hits.Add(1);
}

app.Use(async (ctx, next) =>
{
    var sw = Stopwatch.StartNew();
    await next();
    sw.Stop();
    if (sw.ElapsedMilliseconds > 500)
    {
        logger.LogWarning(
            "Slow request {Method} {Path} {Ms}ms Tenant={Tenant} TraceId={TraceId}",
            ctx.Request.Method,
            ctx.Request.Path,
            sw.ElapsedMilliseconds,
            ctx.User.FindFirstValue("tenant_id"),
            Activity.Current?.TraceId);
    }
});
